curl -s -X POST http://aws:4566/ -d 'Action=ListQueues&Version=2012-11-05' -H 'Content-Type: application/x-www-form-urlencoded' | head -c 500; echo
aws ec2 describe-subnets --query 'Subnets[].[SubnetId,AvailabilityZone,CidrBlock]' --output text; aws ec2 describe-security-groups --query 'SecurityGroups[].[GroupId,GroupName]' --output text

mkdir -p /workspace/submission/infra && cd /workspace/submission/infra
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.51.0"
    }
  }
}
EOF
cat > variables.tf <<'EOF'
variable "config_path" {
  description = "Path to the deployment inputs (resource_prefix, region, db credentials, images)."
  type        = string
  default     = "/workspace/config/config.json"
}
EOF
cat > provider.tf <<'EOF'
locals {
  cfg      = jsondecode(file(var.config_path))
  prefix   = local.cfg.resource_prefix
  region   = local.cfg.region
  endpoint = local.cfg.aws_endpoint_url

  tags = {
    ClearLedgerDeployment = local.prefix
  }

  service_endpoints = [
    "ec2", "elbv2", "ecs", "rds", "dynamodb", "elasticache", "s3", "sqs", "lambda",
    "scheduler", "cognitoidp", "iam", "kms", "cloudwatchlogs", "sts",
  ]
}

provider "aws" {
  region     = local.region
  access_key = "test"
  secret_key = "test"

  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  s3_use_path_style           = true

  dynamic "endpoints" {
    for_each = [local.endpoint]
    content {
      ec2            = endpoints.value
      elbv2          = endpoints.value
      ecs            = endpoints.value
      rds            = endpoints.value
      dynamodb       = endpoints.value
      elasticache    = endpoints.value
      s3             = endpoints.value
      sqs            = endpoints.value
      lambda         = endpoints.value
      scheduler      = endpoints.value
      cognitoidp     = endpoints.value
      iam            = endpoints.value
      kms            = endpoints.value
      cloudwatchlogs = endpoints.value
      sts            = endpoints.value
    }
  }

  default_tags {
    tags = local.tags
  }
}

data "aws_caller_identity" "current" {}
EOF

cd /workspace/submission/infra
cat > logs.tf <<'EOF'
locals {
  log_groups = {
    api       = "/clearledger/${local.prefix}/api"
    projector = "/clearledger/${local.prefix}/projector"
    relay     = "/clearledger/${local.prefix}/outbox-relay"
    archiver  = "/clearledger/${local.prefix}/audit-archiver"
  }
}

resource "aws_cloudwatch_log_group" "this" {
  for_each          = local.log_groups
  name              = each.value
  retention_in_days = 14

  tags = merge(local.tags, { ClearLedgerRole = each.key })
}
EOF
cat > kms.tf <<'EOF'
locals {
  account_id = data.aws_caller_identity.current.account_id
  root_arn   = "arn:aws:iam::${local.account_id}:root"

  # Roles authorised to use each key.
  kms_users = {
    database   = ["relay", "archiver"]
    messaging  = ["ecs_task", "projector", "relay"]
    projection = ["ecs_task", "projector"]
    audit      = ["archiver"]
  }
  role_names = ["ecs_execution", "ecs_task", "projector", "relay", "archiver", "scheduler"]
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_users
  description             = "ClearLedger ${each.key} key (${local.prefix})"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.prefix}-${each.key}"
    Statement = [
      {
        Sid       = "AccountRootAdministration"
        Effect    = "Allow"
        Principal = { AWS = local.root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AuthorizedWorkloadCryptoUse"
        Effect    = "Allow"
        Principal = { AWS = [for r in each.value : aws_iam_role.this[r].arn] }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource  = "*"
      },
      {
        Sid       = "DenyKeyLifecycleForAllWorkloads"
        Effect    = "Deny"
        Principal = { AWS = [for r in local.role_names : aws_iam_role.this[r].arn] }
        Action    = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
        Resource  = "*"
      },
      {
        Sid    = "DenyCryptoForUnauthorizedWorkloads"
        Effect = "Deny"
        Principal = {
          AWS = [for r in local.role_names : aws_iam_role.this[r].arn if !contains(each.value, r)]
        }
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = "*"
      },
    ]
  })

  tags = merge(local.tags, { Name = "${local.prefix}-${each.key}", ClearLedgerKeyUsage = each.key })
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_users
  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}
EOF

cd /workspace/submission/infra
cat > iam.tf <<'EOF'
locals {
  role_trust = {
    ecs_execution = "ecs-tasks.amazonaws.com"
    ecs_task      = "ecs-tasks.amazonaws.com"
    projector     = "lambda.amazonaws.com"
    relay         = "lambda.amazonaws.com"
    archiver      = "lambda.amazonaws.com"
    scheduler     = "scheduler.amazonaws.com"
  }

  # Resource ARNs, built from names so the policies never depend on resources
  # that in turn depend on the roles.
  q_arn      = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  gsi_arn    = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn
  kms_arn    = { for k, v in aws_kms_key.this : k => v.arn }
  fn_arn     = { for k, v in aws_lambda_function.this : k => v.arn }

  logs_base = "arn:aws:logs:${local.region}:${local.account_id}:log-group:"
  lg_arn    = { for k, v in local.log_groups : k => "${local.logs_base}${v}*" }

  all_kms_arns = [for k in ["database", "messaging", "projection", "audit"] : local.kms_arn[k]]
  s3_arns      = [local.bucket_arn, "${local.bucket_arn}/*"]
  ddb_arns     = [local.table_arn, local.gsi_arn]
  both_queues  = [local.q_arn, local.dlq_arn]

  # Own log group per logging workload.
  own_log = {
    ecs_execution = "api"
    ecs_task      = "api"
    projector     = "projector"
    relay         = "relay"
    archiver      = "archiver"
  }

  log_write = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  crypto    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]

  deny_key_lifecycle = {
    Sid      = "DenyKmsKeyLifecycle"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms_arns
  }

  # Deny log writes on every log group except the workload's own.
  deny_foreign_logs = { for r in keys(local.own_log) : r => {
    Sid      = "DenyForeignLogGroups"
    Effect   = "Deny"
    Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    Resource = [for k, v in local.lg_arn : v if k != local.own_log[r]]
  } }

  allow_own_logs = { for r, g in local.own_log : r => {
    Sid      = "WriteOwnLogGroup"
    Effect   = "Allow"
    Action   = local.log_write
    Resource = [local.lg_arn[g]]
  } }

  deny_ddb_all = {
    Sid      = "DenyDynamoDbAccess"
    Effect   = "Deny"
    Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
    Resource = local.ddb_arns
  }
  deny_s3_all = {
    Sid      = "DenyAuditBucketAccess"
    Effect   = "Deny"
    Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    Resource = local.s3_arns
  }
  deny_sqs_all = {
    Sid      = "DenyQueueAccess"
    Effect   = "Deny"
    Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
    Resource = local.both_queues
  }

  role_policies = {
    ecs_execution = [
      local.allow_own_logs["ecs_execution"],
      local.deny_key_lifecycle,
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = local.all_kms_arns
      },
      local.deny_foreign_logs["ecs_execution"],
    ]

    ecs_task = [
      {
        Sid      = "PublishToEventQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = local.ddb_arns
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.crypto
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      local.allow_own_logs["ecs_task"],
      local.deny_key_lifecycle,
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyDeadLetterQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyForeignKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms_arn["database"], local.kms_arn["audit"]]
      },
      local.deny_foreign_logs["ecs_task"],
    ]

    projector = [
      {
        Sid      = "ConsumeEventQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "ForwardToDeadLetterQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = local.ddb_arns
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.crypto
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      local.allow_own_logs["projector"],
      local.deny_key_lifecycle,
      {
        Sid      = "DenyPublishToMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyConsumeDeadLetterQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionDeletes"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyForeignKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms_arn["database"], local.kms_arn["audit"]]
      },
      local.deny_foreign_logs["projector"],
    ]

    relay = [
      {
        Sid      = "PublishToEventQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "UseMessagingAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.crypto
        Resource = [local.kms_arn["messaging"], local.kms_arn["database"]]
      },
      local.allow_own_logs["relay"],
      local.deny_key_lifecycle,
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyDeadLetterQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyForeignKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms_arn["projection"], local.kms_arn["audit"]]
      },
      local.deny_foreign_logs["relay"],
    ]

    archiver = [
      {
        Sid      = "AppendAuditObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource = ["${local.bucket_arn}/ledger-audit/*"]
      },
      {
        Sid      = "AuditBucketMetadata"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [local.bucket_arn]
      },
      {
        Sid      = "UseAuditAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.crypto
        Resource = [local.kms_arn["audit"], local.kms_arn["database"]]
      },
      local.allow_own_logs["archiver"],
      local.deny_key_lifecycle,
      {
        Sid      = "DenyAuditDeletes"
        Effect   = "Deny"
        Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource = local.s3_arns
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      {
        Sid      = "DenyForeignKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      local.deny_foreign_logs["archiver"],
    ]

    scheduler = [
      {
        Sid      = "InvokeScheduledWorkers"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = [local.fn_arn["relay"], local.fn_arn["archiver"]]
      },
      local.deny_key_lifecycle,
      {
        Sid      = "DenyInvokeProjector"
        Effect   = "Deny"
        Action   = ["lambda:InvokeFunction"]
        Resource = [local.fn_arn["projector"]]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyKmsCrypto"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = local.all_kms_arns
      },
      {
        Sid      = "DenyAllLogWrites"
        Effect   = "Deny"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = values(local.lg_arn)
      },
    ]
  }
}

resource "aws_iam_role" "this" {
  for_each = local.role_trust
  name     = "${local.prefix}-${replace(each.key, "_", "-")}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = each.value }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = merge(local.tags, { ClearLedgerRole = each.key })
}

resource "aws_iam_role_policy" "this" {
  for_each = local.role_policies
  name     = "${local.prefix}-${replace(each.key, "_", "-")}-policy"
  role     = aws_iam_role.this[each.key].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = each.value
  })
}
EOF

cd /workspace/submission/infra
cat > messaging.tf <<'EOF'
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600

  tags = merge(local.tags, { Name = "${local.prefix}-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = merge(local.tags, { Name = "${local.prefix}-events" })
}

locals {
  r_arn = { for k, v in aws_iam_role.this : k => v.arn }

  q_allow_publish = [local.r_arn["ecs_task"], local.r_arn["relay"]]
}

resource "aws_sqs_queue_policy" "main" {
  queue_url = aws_sqs_queue.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.prefix}-events-policy"
    Statement = [
      {
        Sid       = "AllowPublishers"
        Effect    = "Allow"
        Principal = { AWS = local.q_allow_publish }
        Action    = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource  = aws_sqs_queue.main.arn
      },
      {
        Sid       = "AllowProjectorConsume"
        Effect    = "Allow"
        Principal = { AWS = local.r_arn["projector"] }
        Action    = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource  = aws_sqs_queue.main.arn
      },
      {
        Sid    = "DenySendFromNonPublishers"
        Effect = "Deny"
        Principal = {
          AWS = [for r in ["ecs_execution", "projector", "archiver", "scheduler"] : local.r_arn[r]]
        }
        Action   = ["sqs:SendMessage"]
        Resource = aws_sqs_queue.main.arn
      },
      {
        Sid    = "DenyConsumeFromNonConsumers"
        Effect = "Deny"
        Principal = {
          AWS = [for r in ["ecs_execution", "ecs_task", "relay", "archiver", "scheduler"] : local.r_arn[r]]
        }
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = aws_sqs_queue.main.arn
      },
    ]
  })
}

resource "aws_sqs_queue_policy" "dlq" {
  queue_url = aws_sqs_queue.dlq.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.prefix}-events-dlq-policy"
    Statement = [
      {
        Sid       = "AllowProjectorDeadLetter"
        Effect    = "Allow"
        Principal = { AWS = local.r_arn["projector"] }
        Action    = ["sqs:SendMessage"]
        Resource  = aws_sqs_queue.dlq.arn
      },
      {
        Sid       = "DenyConsumeFromAllWorkloads"
        Effect    = "Deny"
        Principal = { AWS = [for r in local.role_names : local.r_arn[r]] }
        Action    = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource  = aws_sqs_queue.dlq.arn
      },
      {
        Sid    = "DenySendFromNonProjectors"
        Effect = "Deny"
        Principal = {
          AWS = [for r in ["ecs_execution", "ecs_task", "relay", "archiver", "scheduler"] : local.r_arn[r]]
        }
        Action   = ["sqs:SendMessage"]
        Resource = aws_sqs_queue.dlq.arn
      },
    ]
  })
}
EOF
cat > data_stores.tf <<'EOF'
# ---------------------------------------------------------------- DynamoDB
resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projections" })
}

# ---------------------------------------------------------------------- S3
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-audit"
  force_destroy = true

  tags = merge(local.tags, { Name = "${local.prefix}-audit" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "audit" {
  bucket = aws_s3_bucket.audit.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ArchiverObjectAccess"
        Effect    = "Allow"
        Principal = { AWS = local.r_arn["archiver"] }
        Action    = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource  = "${aws_s3_bucket.audit.arn}/ledger-audit/*"
      },
      {
        Sid       = "ArchiverBucketAccess"
        Effect    = "Allow"
        Principal = { AWS = local.r_arn["archiver"] }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.audit.arn
      },
      {
        Sid       = "DenyDeletesForAllWorkloads"
        Effect    = "Deny"
        Principal = { AWS = [for r in local.role_names : local.r_arn[r]] }
        Action    = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource  = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
      },
      {
        Sid    = "DenyWritesForNonArchivers"
        Effect = "Deny"
        Principal = {
          AWS = [for r in ["ecs_execution", "ecs_task", "projector", "relay", "scheduler"] : local.r_arn[r]]
        }
        Action   = ["s3:PutObject"]
        Resource = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.audit]
}

